import fs from 'node:fs';
import vm from 'node:vm';

// 从保留的完整鉴别数据生成理化子集，不向浏览器加载显微、薄层模板。
const source = new URL('../assets/identification-templates.js', import.meta.url);
const output = new URL('../assets/physicochemical-templates.js', import.meta.url);
const context = vm.createContext({});
vm.runInContext(fs.readFileSync(source, 'utf8'), context);
const templates = vm.runInContext('IDENTIFICATION_TEMPLATES', context)
  .filter(template => template.item === 'physicochemical');
if (!templates.length) throw new Error('理化模板为空');
fs.writeFileSync(output,
  '/* Generated by tools/build_physicochemical_templates.mjs from preserved local inspection records. */\n'
  + `const PHYSICOCHEMICAL_TEMPLATES = ${JSON.stringify(templates)};\n`, 'utf8');
console.log(`Generated ${templates.length} physicochemical templates`);
